// Workspace access controls: pending intent without granting access before confirmation.
const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),http=require('node:http');
const {execFileSync}=require('node:child_process'),{chromium}=require(process.env.AGENTNET_PLAYWRIGHT);
const web=path.resolve(__dirname,'../web'),work=fs.mkdtempSync(path.join(os.tmpdir(),'agentnet-google-access-'));
const entry=`
import React from 'react';import {createRoot} from 'react-dom/client';
import {Store,useStore} from './src/store';import {StoreContext} from './src/context';import {OwnedContext} from './src/owned';import {GoogleMembers} from './src/features/GoogleMembers';
const root=document.getElementById('root'),app=document.getElementById('app'),portals=document.getElementById('portals');
const overview={seq:1,version:'fixture',me:{address:'self/laptop',fingerprint:'fixture-key'},person:{person:'self'},people:[],dms:[],threads:[],needs_you:[]};
const access={workspace_url:'https://fixture.invalid',enabled:true,can_admin:true,emails:[{email:'member@example.com',denied:false,admin:false},{email:'blocked@example.com',denied:true,admin:false}],domains:['existing.example']};
const f=window.fixture={writes:[],reads:[],holdReads:false,overview,access};
const host={platform:'daemon',workspace:{id:'google-access',state:'enrolled'},listen(){return()=>{}},async api(p,b){
 if(p.startsWith('/api/overview'))return structuredClone(overview);
 if(p==='/api/google/access'){if(b!==undefined)return new Promise((resolve,reject)=>f.writes.push({b:structuredClone(b),resolve,reject}));const snapshot=structuredClone(access);if(f.holdReads)await new Promise(resolve=>f.reads.push(resolve));return snapshot;}
 if(p.startsWith('/api/agents'))return {agents:[]};return {};
}};
const store=new Store(host);f.store=store;
f.finish=(i,fail=false,commit=!fail)=>{const w=f.writes[i],c=w.b;if(commit){if(c.domain){const d=c.domain.trim().replace(/^@/,'').toLowerCase();access.domains=access.domains.filter(x=>x!==d);if(!c.remove)access.domains.push(d)}else{const email=c.email.trim().toLowerCase();access.emails=access.emails.filter(x=>x.email!==email);access.emails.push({email,denied:c.remove,admin:false})}}if(fail)w.reject(Error('Invented access refusal'));else w.resolve({})};
f.owner=async()=>{overview.person={person:'other'};overview.seq++;await store.refetch()};
f.release=()=>{f.holdReads=false;for(const resolve of f.reads.splice(0))resolve()};
function App(){const s=useStore(store,s=>s);return <><button onClick={()=>store.showTab(s.tab==='settings'?'chats':'settings')}>Toggle view</button>
 {s.tab==='settings'?<GoogleMembers/>:<p>Another view</p>}<textarea aria-label="Unrelated draft"/></>}
await store.start();store.showTab('settings');createRoot(app).render(<OwnedContext.Provider value={{root,app,portals}}><StoreContext.Provider value={store}><App/></StoreContext.Provider></OwnedContext.Provider>);
`;
const aliases={'optimistic.mjs':'static/optimistic.mjs','pictures.mjs':'static/pictures.mjs','person-topics.mjs':'skins/shared/person-topics.mjs','reaction-preferences.mjs':'skins/shared/reaction-preferences.mjs','collective-mentions.mjs':'skins/shared/collective-mentions.mjs','drive-space.mjs':'skins/shared/drivespace.mjs','drive-setup.mjs':'skins/shared/drivespace-setup.mjs'};
fs.cpSync(path.join(web,'src'),path.join(work,'src'),{recursive:true});
if(process.env.AGENTNET_GOOGLE_ACCESS_SOURCE)fs.copyFileSync(process.env.AGENTNET_GOOGLE_ACCESS_SOURCE,path.join(work,'src/features/GoogleMembers.tsx'));
for(const [a,b] of Object.entries(aliases))fs.copyFileSync(path.resolve(web,'../',b),path.join(work,'src',a));
fs.symlinkSync(path.join(web,'node_modules'),path.join(work,'node_modules'),'dir');
const js=require(path.join(web,'node_modules/esbuild')).buildSync({stdin:{contents:entry,resolveDir:work,loader:'tsx'},bundle:true,format:'esm',target:'es2022',jsx:'automatic',define:{'process.env.NODE_ENV':'"production"'},write:false}).outputFiles[0].text;
execFileSync(process.execPath,[path.join(web,'node_modules/@tailwindcss/cli/dist/index.mjs'),'-i',path.join(work,'src/styles.css'),'-o',path.join(work,'style.css'),'--minify'],{cwd:work,stdio:'pipe'});
const css=fs.readFileSync(path.join(work,'style.css'));
const server=http.createServer((req,res)=>{if(req.url==='/entry.mjs'){res.setHeader('Content-Type','text/javascript');return res.end(js)}if(req.url==='/style.css'){res.setHeader('Content-Type','text/css');return res.end(css)}res.setHeader('Content-Type','text/html');res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workspace access fixture</title><link rel="icon" href="data:,"><link rel="stylesheet" href="/style.css"><div id="root" class="an-root"><div id="app" class="an-app"></div><div id="portals"></div></div><script type="module" src="/entry.mjs"></script>')});
(async()=>{let browser;const reports=[];try{
 await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({headless:true});
 const setup=async(width)=>{const page=await browser.newPage({viewport:{width,height:900}});page.setDefaultTimeout(5000);await page.goto('http://127.0.0.1:'+server.address().port);await page.getByLabel('Invite by email',{exact:true}).waitFor();return page};
 const pending=page=>page.getByRole('region',{name:'Workspace access change',exact:true});
 const submit=async(page,action)=>{await page.getByLabel('Invite by email',{exact:true}).fill('new@example.com');await page.getByLabel('Allow everyone at @domain',{exact:true}).fill('new.example');const button=page.getByRole('button',{name:action,exact:true});await button.evaluate(b=>b.addEventListener('click',e=>fixture.input={at:performance.now(),trusted:e.isTrusted},{once:true,capture:true}));await button.click();await pending(page).waitFor({timeout:500})};
 const capture=async(page,name)=>{if(process.env.AGENTNET_GOOGLE_ACCESS_EVIDENCE)await page.screenshot({path:process.env.AGENTNET_GOOGLE_ACCESS_EVIDENCE+'-'+name+'.png',fullPage:true})};
 for(const width of [1440,390])for(const action of ['Invite by email','Allow domain','Remove access','Remove domain','Invite again']){
  const page=await setup(width),errors=[];page.on('pageerror',e=>errors.push(String(e)));const before=await page.evaluate(()=>structuredClone(fixture.access));await submit(page,action);
  const timing=await page.evaluate(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return {...fixture.input,feedbackMs:performance.now()-fixture.input.at}});assert(timing.trusted&&timing.feedbackMs<500,JSON.stringify(timing));
  assert(await pending(page).evaluate(el=>{const r=el.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&r.left>=0&&r.right<=innerWidth}));assert.equal(await page.getByLabel('Invite by email',{exact:true}).count(),0);assert.deepEqual(await page.evaluate(()=>fixture.access),before,'pending UI does not grant/revoke canonical access');assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),true);
  const target=await page.evaluate(()=>fixture.writes[0].b);assert((await pending(page).innerText()).includes(target.email||target.domain));assert.equal(await page.evaluate(()=>{const a=fixture.store.api.changeGoogleAccess(fixture.writes[0].b),b=fixture.store.api.changeGoogleAccess(fixture.writes[0].b);a.catch(()=>{});b.catch(()=>{});return a===b}),true);assert.equal(await page.evaluate(()=>fixture.writes.length),1);if(action==='Invite by email')await capture(page,'pending-'+width);
  await page.getByRole('button',{name:'Toggle view',exact:true}).click();await page.getByText('Another view',{exact:true}).waitFor();await page.getByLabel('Unrelated draft').fill('Keep unrelated input');await page.evaluate(()=>fixture.finish(0,true));await page.waitForFunction(()=>fixture.store.get().toasts.some(t=>t.text.includes('Access change not confirmed')));await page.getByRole('button',{name:'Toggle view',exact:true}).click();await pending(page).getByRole('alert').waitFor();if(action==='Invite by email')await capture(page,'error-'+width);
  await pending(page).getByRole('button',{name:'Retry access change',exact:true}).click();await page.waitForFunction(()=>fixture.writes.length===2);assert.deepEqual(await page.evaluate(()=>fixture.writes[1].b),target);await page.evaluate(()=>{fixture.holdReads=true;fixture.finish(1)});await page.getByText('Access change saved; checking current access',{exact:true}).waitFor();if(action==='Invite by email')await capture(page,'checking-'+width);await page.evaluate(()=>fixture.store.api.changeGoogleAccess(fixture.writes[1].b));assert.equal(await page.evaluate(()=>fixture.writes.length),2);await page.evaluate(()=>fixture.release());await pending(page).waitFor({state:'hidden'});await page.getByLabel('Invite by email',{exact:true}).waitFor();assert.equal(await page.getByLabel('Unrelated draft').inputValue(),'Keep unrelated input');assert.deepEqual(errors,[]);reports.push({width,action,feedbackMs:timing.feedbackMs});await page.close();
 }
 for(const mode of ['stopped','before-admission','lost-reply','changed-owner','permission-lost','retained-drafts','check-only']){
  const page=await setup(390);
  if(mode==='before-admission'){assert.equal(await page.evaluate(async()=>{const work=fixture.store.api.changeGoogleAccess({email:'new@example.com',remove:false});fixture.store.stop();await work.catch(()=>{});return fixture.writes.length}),0)}
  else if(mode==='retained-drafts'){await page.getByLabel('Invite by email',{exact:true}).fill('draft@example.com');await page.getByLabel('Allow everyone at @domain',{exact:true}).fill('draft.example');await page.getByRole('button',{name:'Toggle view',exact:true}).click();await page.getByRole('button',{name:'Toggle view',exact:true}).click();assert.equal(await page.getByLabel('Invite by email',{exact:true}).inputValue(),'draft@example.com');assert.equal(await page.getByLabel('Allow everyone at @domain',{exact:true}).inputValue(),'draft.example')}
  else{await submit(page,'Invite by email');if(mode==='stopped'){assert.equal(await page.evaluate(async()=>{fixture.store.stop();const s=fixture.store.get();fixture.finish(0,false,false);await new Promise(r=>setTimeout(r,35));return fixture.store.get()===s}),true)}else if(mode==='lost-reply'){await page.evaluate(()=>fixture.finish(0,true,true));await pending(page).getByRole('alert').waitFor();await pending(page).getByText('Last checked email status: allowed.',{exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.writes.length),1);await pending(page).getByRole('button',{name:'Dismiss status',exact:true}).click();await pending(page).waitFor({state:'hidden'});assert.equal(await page.evaluate(()=>fixture.writes.length),1)}else if(mode==='changed-owner'){await page.evaluate(()=>fixture.owner());await pending(page).waitFor({state:'hidden'});await page.evaluate(()=>fixture.finish(0,false,false));await page.waitForTimeout(35);assert.equal(await page.evaluate(()=>fixture.store.get().googleAccessChange),undefined);assert.equal(await page.getByLabel('Invite by email',{exact:true}).inputValue(),'')}else if(mode==='permission-lost'){await page.evaluate(()=>{fixture.access.can_admin=false;fixture.finish(0,true)});await pending(page).getByText('You no longer have permission to change access here.',{exact:true}).waitFor();assert.equal(await pending(page).getByRole('button',{name:'Retry access change',exact:true}).isDisabled(),true);await pending(page).getByRole('button',{name:'Dismiss status',exact:true}).click();await pending(page).waitFor({state:'hidden'});assert.equal(await page.getByRole('button',{name:'Invite by email',exact:true}).count(),0)}else{await page.evaluate(()=>fixture.finish(0,true));await pending(page).getByRole('alert').waitFor();await page.evaluate(()=>{fixture.holdReads=true});await pending(page).getByRole('button',{name:'Check current access',exact:true}).click();await page.getByRole('button',{name:'Checking access…',exact:true}).waitFor();await page.evaluate(()=>fixture.release());await page.getByRole('button',{name:'Check current access',exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.writes.length),1)}}
  await page.close();
 }
 console.log(JSON.stringify({ok:true,reports,scope:'actual GoogleMembers and Store; five controls at both widths, held/refused writes, exact retry, remount, saved readback, retained drafts, lost response, revoked permission, changed owner and stopped workspace; native authority never projected; synthetic host'}));
 }finally{await browser?.close();await new Promise(r=>server.close(r));fs.rmSync(work,{recursive:true,force:true})}
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
